using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Globalization;
using System.Linq;
using Avalonia.Threading;

namespace Pixeval.Localization;

/// <summary>Coordinates application culture and UI invalidation; messages are generated by ZeroI18n.</summary>
public sealed class AppLocalization
{
    public static AppLocalization Instance { get; } = new();
    private readonly CultureInfo _systemCulture = CultureInfo.CurrentUICulture;
    private readonly List<WeakReference<Action>> _listeners = [];
    public CultureInfo CurrentCulture => CultureInfo.GetCultureInfo(Strings.CurrentLocale);
    public IReadOnlyList<CultureInfo> SupportedLanguages { get; } =
        Strings.SupportedLocales.Select(CultureInfo.GetCultureInfo).ToArray();
    public IReadOnlyList<CultureInfo> AvailableLanguages { get; }

    private AppLocalization()
    {
        AvailableLanguages = [new SystemLanguage(), .. SupportedLanguages];
        Strings.CurrentLocaleChanged += NotifyChanged;
    }

    public string ResolveLanguage(string? name)
    {
        CultureInfo requested;
        try { requested = string.IsNullOrWhiteSpace(name) ? _systemCulture : CultureInfo.GetCultureInfo(name); }
        catch (CultureNotFoundException) { requested = _systemCulture; }
        for (var culture = requested; !Equals(culture, CultureInfo.InvariantCulture); culture = culture.Parent)
        {
            var exact = SupportedLanguages.FirstOrDefault(c => c.Name.Equals(culture.Name, StringComparison.OrdinalIgnoreCase));
            if (exact is not null) return exact.Name;
        }
        return SupportedLanguages.FirstOrDefault(c => c.TwoLetterISOLanguageName == requested.TwoLetterISOLanguageName)?.Name
               ?? Strings.DefaultLocale;
    }

    public void SetLanguage(string? cultureName)
    {
        if (!Dispatcher.UIThread.CheckAccess())
        {
            Dispatcher.UIThread.Post(() => SetLanguage(cultureName));
            return;
        }
        var locale = ResolveLanguage(cultureName);
        var culture = CultureInfo.GetCultureInfo(locale);
        CultureInfo.CurrentCulture = CultureInfo.CurrentUICulture = culture;
        CultureInfo.DefaultThreadCurrentCulture = CultureInfo.DefaultThreadCurrentUICulture = culture;
        Strings.CurrentLocale = locale;
    }

    /// <summary>The owner retains the returned token. The singleton never roots the owner.</summary>
    public IDisposable Subscribe(Action changed)
    {
        var weak = new WeakReference<Action>(changed);
        lock (_listeners) _listeners.Add(weak);
        return new Subscription(this, weak, changed);
    }

    private void NotifyChanged()
    {
        if (!Dispatcher.UIThread.CheckAccess()) { Dispatcher.UIThread.Post(NotifyChanged); return; }
        WeakReference<Action>[] listeners;
        lock (_listeners) listeners = _listeners.ToArray();
        if (AvailableLanguages[0] is SystemLanguage system) system.Refresh();
        foreach (var weak in listeners)
            if (weak.TryGetTarget(out var changed)) changed();
            else { lock (_listeners) _listeners.Remove(weak); }
    }

    private sealed class Subscription(AppLocalization owner, WeakReference<Action> weak, Action callback) : IDisposable
    {
        private Action? _callback = callback;
        public void Dispose() { lock (owner._listeners) owner._listeners.Remove(weak); _callback = null; }
    }

    private sealed class SystemLanguage : CultureInfo, INotifyPropertyChanged
    {
        public SystemLanguage() : base("") { }
        public event PropertyChangedEventHandler? PropertyChanged;
        public void Refresh() => PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(string.Empty));
        public override string NativeName => Strings.SettingsMainViewLanguageSystemDefault();
        public override string DisplayName => NativeName;
        public override string ToString() => "";
    }
}
